\begin{tikzpicture}[x=0.85cm,y=0.65cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{curveBlue}{HTML}{268CFF}
\path[use as bounding box] (-0.6,-2.65) rectangle (6.9,2.7);
\draw[->,line width=0.5pt] (-0.08,0)--(6.7,0) node[right] {$x$};
\draw[<->,line width=0.5pt] (0,-2.3)--(0,2.3) node[above] {$y$};
\foreach \k in {1,...,12}{\draw[line width=0.4pt] ({\k*pi/6},-0.055)--({\k*pi/6},0.055);}
\foreach \v/\lab in {1.570796/{\frac{\pi}{2}},3.141593/{\pi},4.712389/{\frac{3\pi}{2}},6.283185/{2\pi}}{\node[below=3pt] at (\v,0) {\special{dvisvgm:raw <g data-graph-text="tick">}$\lab$\special{dvisvgm:raw </g>}};}
\foreach \v in {-2,-1,1,2}{\draw[line width=0.4pt] (-0.055,\v)--(0.055,\v);\node[left=2pt] at (0,\v) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};}
\draw[curveBlue,line width=0.8pt,domain=0:6.283185,samples=181] plot (\x,{2*sin((\x-pi/3)*180/pi)});
\fill[curveBlue] (0,{-sqrt(3)}) circle (1.3pt);
\fill[curveBlue] ({2*pi},{-sqrt(3)}) circle (1.3pt);
\end{tikzpicture}

